script.source:
return ['_doc': ctx.payload.hits.hits.stream().map(
        v -> {v.get('_source').put('index', v.get('_index'));
        v.remove('_index');
        v.remove('_type');
        v.get('_source').put('threat.detection', ctx.watch_id);
        v.get('_source').put('threat.framework', 'MITRE ATT&CK');
        v.get('_source').put('threat.technique.id', 'T1068');
        v.get('_source').put('threat.technique.name', 'Exploitation for Privilege Escalation');
        v.get('_source').put('threat.technique.reference', 'https://attack.mitre.org/techniques/T1068');
        v.get('_source').put('threat.tactic.id', 'TA0004');
        v.get('_source').put('threat.tactic.name', 'Privilege Escalation');
        v.get('_source').put('threat.tactic.reference', 'https://attack.mitre.org/tactics/TA0004');
        v.get('_source').put('event.timestamp_detected', ctx.trigger.triggered_time);
        v.get('_source').put('threat.is_alert', true);
        v.get('_source').put('threat.alert_type', 'AWS Security Hub vulnerable Privilege Escalation activity');
        v.get('_source').put('threat.detection_description', 'Detects AWS GuardDuty Privilege Escalation type attacks.');
        v.get('_source').put('threat.severity', 'high');
        v.get('_source').put('threat.triage_score', 60);
        v.get('_source').put('threat.ratingtime_sla_applies', 'true');
        v.get('_source').put('id', v.get('_id'));
        return v.get('_source')}).collect(Collectors.toList())]
